const CLASSES = [{"id": "barbarian", "name": "Barbaro", "originalName": "Barbarian", "source": "PHB 2024", "hitDie": "12", "image": "https://5e.tools/img/classes/XPHB/Barbarian.webp", "primaryAbility": ["STR"], "proficiencies": ["Str", "Con"], "tableLabels": ["Rages", "Rage Damage", "Weapon Mastery"], "progression": [{"level": 1, "values": ["2", "+2", "2"]}, {"level": 2, "values": ["2", "+2", "2"]}, {"level": 3, "values": ["3", "+2", "2"]}, {"level": 4, "values": ["3", "+2", "3"]}, {"level": 5, "values": ["3", "+2", "3"]}, {"level": 6, "values": ["4", "+2", "3"]}, {"level": 7, "values": ["4", "+2", "3"]}, {"level": 8, "values": ["4", "+2", "3"]}, {"level": 9, "values": ["4", "+3", "3"]}, {"level": 10, "values": ["4", "+3", "4"]}, {"level": 11, "values": ["4", "+3", "4"]}, {"level": 12, "values": ["5", "+3", "4"]}, {"level": 13, "values": ["5", "+3", "4"]}, {"level": 14, "values": ["5", "+3", "4"]}, {"level": 15, "values": ["5", "+3", "4"]}, {"level": 16, "values": ["5", "+4", "4"]}, {"level": 17, "values": ["6", "+4", "4"]}, {"level": 18, "values": ["6", "+4", "4"]}, {"level": 19, "values": ["6", "+4", "4"]}, {"level": 20, "values": ["6", "+4", "4"]}], "subclasses": [{"name": "Path of the Berserker", "shortName": "Berserker", "source": "PHB 2024", "desc": ""}, {"name": "Path of the Wild Heart", "shortName": "Wild Heart", "source": "PHB 2024", "desc": ""}, {"name": "Path of the World Tree", "shortName": "World Tree", "source": "PHB 2024", "desc": ""}, {"name": "Path of the Zealot", "shortName": "Zealot", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Rage", "level": 1, "text": "You can imbue yourself with a primal power called Rage, a force that grants you extraordinary might and resilience. You can enter it as a Bonus Action if you aren't wearing Heavy armor. You can enter your Rage the number of times shown for your Barbarian level in the Rages column of the Barbarian Features table. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. While active, your Rage follows the rules below. Damage Resistance. You have Resistance to Bludgeoning, Piercing, and Slashing damage. Rage Damage. When you make an attack using Strength—with either a weapon or an Unarmed Strike—and deal damage to the target, you gain a bonus to the damage that increases as you gain levels as a Barbarian, as shown in the Rage Damage column of the Barbarian Features table. Strength Advantage. You have Advantage on Strength checks and Strength saving throws. No Concentration or Spells. You can't maintain Concentration|XPHB, and you can't cast spells. Duration. The Rage lasts until the end of your next turn, and it ends early if you don Heavy armor or have the Incapacitated condition. If your Rage is still active on your next turn, you can extend the Rage for another round by doing one of the following: Make an attack roll against an enemy. Force an enemy to make a saving throw. Take a Bonus Action to extend your Rage. Each time the Rage is extended, it lasts until the end of your next turn. You can maintain a Rage for up to 10 minutes."}, {"name": "Unarmored Defense", "level": 1, "text": "While you aren't wearing any armor, your base Armor Class equals 10 plus your Dexterity and Constitution modifiers. You can use a Shield and still gain this benefit."}, {"name": "Weapon Mastery", "level": 1, "text": "Your training with weapons allows you to use the weapon mastery properties of two kinds of Simple or Martial Melee weapons of your choice, such as Greataxe and Handaxe. Whenever you finish a Long Rest, you can practice weapon drills and change one of those weapon choices. When you reach certain Barbarian levels, you gain the ability to use the weapon mastery properties of more kinds of weapons, as shown in the Weapon Mastery column of the Barbarian Features table."}, {"name": "Danger Sense", "level": 2, "text": "You gain an uncanny sense of when things aren't as they should be, giving you an edge when you dodge perils. You have Advantage on Dexterity saving throws unless you have the Incapacitated condition."}, {"name": "Reckless Attack", "level": 2, "text": "You can throw aside all concern for defense to attack with increased ferocity. When you make your first attack roll on your turn, you can decide to attack recklessly. Doing so gives you Advantage on attack rolls using Strength until the start of your next turn, but attack rolls against you have Advantage during that time."}, {"name": "Barbarian Subclass", "level": 3, "text": "You gain a Barbarian subclass of your choice. A subclass is a specialization that grants you features at certain Barbarian levels. For the rest of your career, you gain each of your subclass's features that are of your Barbarian level or lower."}, {"name": "Primal Knowledge", "level": 3, "text": "You gain proficiency in another skill of your choice from the skill list available to Barbarians at level 1. In addition, while your Rage is active, you can channel primal power when you attempt certain tasks; whenever you make an ability check using one of the following skills, you can make it as a Strength check even if it normally uses a different ability: Acrobatics, Intimidation, Perception, Stealth, or Survival. When you use this ability, your Strength represents primal power coursing through you, honing your agility, bearing, and senses."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Barbarian levels 8, 12, and 16."}, {"name": "Extra Attack", "level": 5, "text": "You can attack twice instead of once whenever you take the Attack action on your turn."}, {"name": "Fast Movement", "level": 5, "text": "Your speed increases by 10 feet while you aren't wearing Heavy armor."}, {"name": "Subclass Feature", "level": 6, "text": "You gain a feature from your Barbarian subclass."}, {"name": "Feral Instinct", "level": 7, "text": "Your instincts are so honed that you have Advantage on Initiative rolls."}, {"name": "Instinctive Pounce", "level": 7, "text": "As part of the Bonus Action you take to enter your Rage, you can move up to half your Speed."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Brutal Strike", "level": 9, "text": "If you use Reckless Attack, you can forgo any Advantage on one Strength-based attack roll of your choice on your turn. The chosen attack roll mustn't have Disadvantage. If the chosen attack roll hits, the target takes an extra 1d10 damage of the same type dealt by the weapon or Unarmed Strike, and you can cause one Brutal Strike effect of your choice. You have the following effect options. Forceful Blow. The target is pushed 15 feet straight away from you. You can then move up to half your Speed straight toward the target without provoking Opportunity Attack. Hamstring Blow. The target's Speed is reduced by 15 feet until the start of your next turn. A target can be affected by only one Hamstring Blow at a time—the most recent one."}, {"name": "Subclass Feature", "level": 10, "text": "You gain a feature from your Barbarian subclass."}, {"name": "Relentless Rage", "level": 11, "text": "Your Rage can keep you fighting despite grievous wounds. If you drop to 0 Hit Points while your Rage is active and don't die outright, you can make a 10 Constitution saving throw. If you succeed, your Hit Points instead change to a number equal to twice your Barbarian level. Each time you use this feature after the first, the DC increases by 5. When you finish a Short Rest or Long Rest, the DC resets to 10."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Improved Brutal Strike", "level": 13, "text": "You have honed new ways to attack furiously. The following effects are now among your Brutal Strike options. Staggering Blow. The target has Disadvantage on the next saving throw it makes, and it can't make Opportunity Attack until the start of your next turn. Sundering Blow. Before the start of your next turn, the next attack roll made by another creature against the target gains a +5 bonus to the roll. An attack roll can gain only one Sundering Blow bonus."}, {"name": "Subclass Feature", "level": 14, "text": "You gain a feature from your Barbarian subclass."}, {"name": "Persistent Rage", "level": 15, "text": "When you roll Initiative, you can regain all expended uses of Rage. After you regain uses of Rage in this way, you can't do so again until you finish a Long Rest. In addition, your Rage is so fierce that it now lasts for 10 minutes without you needing to do anything to extend it from round to round. Your Rage ends early if you have the Unconscious condition (not just the Incapacitated condition) or don Heavy armor."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Improved Brutal Strike", "level": 17, "text": "The extra damage of your Brutal Strike increases to 2d10. In addition, you can use two different Brutal Strike effects whenever you use your Brutal Strike feature."}, {"name": "Indomitable Might", "level": 18, "text": "If your total for a Strength check or Strength saving throw is less than your Strength score, you can use that score in place of the total."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Irresistible Offense is recommended."}, {"name": "Primal Champion", "level": 20, "text": "You embody primal power. Your Strength and Constitution scores increase by 4, to a maximum of 25."}]}, {"id": "bard", "name": "Bardo", "originalName": "Bard", "source": "PHB 2024", "hitDie": "8", "image": "https://5e.tools/img/classes/XPHB/Bard.webp", "primaryAbility": ["CHA"], "proficiencies": ["Dex", "Cha"], "tableLabels": ["Bardic Die", "Cantrips", "Prepared Spells", "1", "2", "3", "4", "5", "6", "7", "8", "9"], "progression": [{"level": 1, "values": ["—", "2", "4"]}, {"level": 2, "values": ["—", "2", "5"]}, {"level": 3, "values": ["—", "2", "6"]}, {"level": 4, "values": ["—", "3", "7"]}, {"level": 5, "values": ["—", "3", "9"]}, {"level": 6, "values": ["—", "3", "10"]}, {"level": 7, "values": ["—", "3", "11"]}, {"level": 8, "values": ["—", "3", "12"]}, {"level": 9, "values": ["—", "3", "14"]}, {"level": 10, "values": ["—", "4", "15"]}, {"level": 11, "values": ["—", "4", "16"]}, {"level": 12, "values": ["—", "4", "16"]}, {"level": 13, "values": ["—", "4", "17"]}, {"level": 14, "values": ["—", "4", "17"]}, {"level": 15, "values": ["—", "4", "18"]}, {"level": 16, "values": ["—", "4", "18"]}, {"level": 17, "values": ["—", "4", "19"]}, {"level": 18, "values": ["—", "4", "20"]}, {"level": 19, "values": ["—", "4", "21"]}, {"level": 20, "values": ["—", "4", "22"]}], "subclasses": [{"name": "College of Dance", "shortName": "Dance", "source": "PHB 2024", "desc": ""}, {"name": "College of Glamour", "shortName": "Glamour", "source": "PHB 2024", "desc": ""}, {"name": "College of Lore", "shortName": "Lore", "source": "PHB 2024", "desc": ""}, {"name": "College of Valor", "shortName": "Valor", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Bardic Inspiration", "level": 1, "text": "You can supernaturally inspire others through words, music, or dance. This inspiration is represented by your Bardic Inspiration die, which is a d6. Using Bardic Inspiration. As a Bonus Action, you can inspire another creature within 60 feet of yourself who can see or hear you. That creature gains one of your Bardic Inspiration dice. A creature can have only one Bardic Inspiration die at a time. Once within the next hour when the creature fails a D20 Test, the creature can roll the Bardic Inspiration die and add the number rolled to the d20, potentially turning the failure into a success. A Bardic Inspiration die is expended when it's rolled. Number of Uses. You can confer a Bardic Inspiration die a number of times equal to your Charisma modifier (minimum of once), and you regain all expended uses when you finish a Long Rest. At Higher Levels. Your Bardic Inspiration die changes when you reach certain Bard levels, as shown in the Bardic Die column of the Bard Features table. The die becomes a d8 at level 5, a d10 at level 10, and a d12 at level 15."}, {"name": "Spellcasting", "level": 1, "text": "You have learned to cast spells through your bardic arts. See chapter 7|XPHB|7 for the rules on spellcasting. The information below details how you use those rules with Bard spells, which appear in the Bard spell list later in the class's description. Cantrips. You know two cantrips of your choice from the Bard spell list. Dancing Lights and Vicious Mockery are recommended. Whenever you gain a Bard level, you can replace one of your cantrips with another cantrip of your choice from the Bard spell list. When you reach Bard levels 4 and 10, you learn another cantrip of your choice from the Bard spell list, as shown in the Cantrips column of the Bard Features table. Spell Slots. The Bard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Bard spell list. Charm Person, Color Spray, Dissonant Whispers, and Healing Word are recommended. The number of spells on your list increases as you gain Bard levels, as shown in the Prepared Spells column of the Bard Features table. Whenever that number increases, choose additional spells from the Bard spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots. For example, if you're a level 3 Bard, your list of prepared spells can include six spells of levels 1 and 2 in any combination. If another Bard feature gives you spells that you always have prepared, those spells don't count against the number of spells you can prepare with this feature, but those spells otherwise count as Bard spells for you. Changing Your Prepared Spells. Whenever you gain a Bard level, you can replace one spell on your list with another Bard spell for which you have spell slots. Spellcasting Ability. Charisma is your spellcasting ability for your Bard spells. Spellcasting Focus. You can use a Musical Instrument as a Spellcasting Focus for your Bard spells."}, {"name": "Expertise", "level": 2, "text": "You gain Expertise in two of your skill proficiencies of your choice. Performance and Persuasion are recommended if you have proficiency in them. At Bard level 9, you gain Expertise in two more of your skill proficiencies of your choice."}, {"name": "Jack of All Trades", "level": 2, "text": "You can add half your Proficiency (round down) to any ability check you make that uses a skill proficiency you lack and that doesn't otherwise use your Proficiency. For example, if you make a Strength (Athletics) check and lack Athletics proficiency, you can add half your Proficiency to the check. A Bard's Repertoire. Does your Bard beat a drum while chanting the deeds of ancient heroes? Strum a lute while crooning romantic tunes? Perform arias of stirring power? Recite dramatic monologues from classic tragedies? Use the rhythm of a folk dance to coordinate the movement of allies in battle? Compose naughty limericks? When you play a Bard, consider the style of artistic performance you favor, the moods you might invoke, and the themes that inspire your own creations. Are your poems inspired by moments of natural beauty, or are they brooding reflections on loss? Do you prefer lofty hymns or rowdy tavern songs? Are you drawn to laments for the fallen or celebrations of joy? Do you dance merry jigs or perform elaborate interpretive choreography? Do you focus on one style of performance or strive to master them all?"}, {"name": "Bard Subclass", "level": 3, "text": "You gain a Bard subclass of your choice. A subclass is a specialization that grants you features at certain Bard levels. For the rest of your career, you gain each of your subclass's features that are of your Bard level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Bard levels 8, 12, and 16."}, {"name": "Font of Inspiration", "level": 5, "text": "You now regain all your expended uses of Bardic Inspiration when you finish a Short Rest or Long Rest. In addition, you can expend a spell slot (no action required) to regain one expended use of Bardic Inspiration."}, {"name": "Subclass Feature", "level": 6, "text": "You gain a feature from your Bard Subclass."}, {"name": "Countercharm", "level": 7, "text": "You can use musical notes or words of power to disrupt mind-influencing effects. If you or a creature within 30 feet of you fails a saving throw against an effect that applies the Charmed or Frightened condition, you can take a Reaction to cause the save to be rerolled, and the new roll has Advantage."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Expertise", "level": 9, "text": "You gain Expertise in two of your Skill Proficiencies of your choice."}, {"name": "Magical Secrets", "level": 10, "text": "You've learned secrets from various magical traditions. Whenever you reach a Bard level (including this level) and the Prepared Spells number in the Bard Features table increases, you can choose any of your new prepared spells from the Bard, Cleric, Druid, and Wizard spell lists, and the chosen spells count as Bard spells for you (see a class's section for its spell list). In addition, whenever you replace a spell prepared for this class, you can replace it with a spell from those lists."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 14, "text": "You gain a feature from your Bard Subclass."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Superior Inspiration", "level": 18, "text": "When you roll Initiative, you regain expended uses of Bardic Inspiration until you have two if you have fewer than that."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Spell Recall is recommended."}, {"name": "Words of Creation", "level": 20, "text": "You have mastered two of the Words of Creation: the words of life and death. You therefore always have the Power Word Heal and Power Word Kill spells prepared. When you cast either spell, you can target a second creature with it if that creature is within 10 feet of the first target."}]}, {"id": "cleric", "name": "Chierico", "originalName": "Cleric", "source": "PHB 2024", "hitDie": "8", "image": "https://5e.tools/img/classes/XPHB/Cleric.webp", "primaryAbility": ["WIS"], "proficiencies": ["Wis", "Cha"], "tableLabels": ["Channel Divinity", "Cantrips", "Prepared Spells", "1", "2", "3", "4", "5", "6", "7", "8", "9"], "progression": [{"level": 1, "values": ["0", "3", "4"]}, {"level": 2, "values": ["2", "3", "5"]}, {"level": 3, "values": ["2", "3", "6"]}, {"level": 4, "values": ["2", "4", "7"]}, {"level": 5, "values": ["2", "4", "9"]}, {"level": 6, "values": ["3", "4", "10"]}, {"level": 7, "values": ["3", "4", "11"]}, {"level": 8, "values": ["3", "4", "12"]}, {"level": 9, "values": ["3", "4", "14"]}, {"level": 10, "values": ["3", "5", "15"]}, {"level": 11, "values": ["3", "5", "16"]}, {"level": 12, "values": ["3", "5", "16"]}, {"level": 13, "values": ["3", "5", "17"]}, {"level": 14, "values": ["3", "5", "17"]}, {"level": 15, "values": ["3", "5", "18"]}, {"level": 16, "values": ["3", "5", "18"]}, {"level": 17, "values": ["3", "5", "19"]}, {"level": 18, "values": ["4", "5", "20"]}, {"level": 19, "values": ["4", "5", "21"]}, {"level": 20, "values": ["4", "5", "22"]}], "subclasses": [{"name": "Life Domain", "shortName": "Life", "source": "PHB 2024", "desc": ""}, {"name": "Light Domain", "shortName": "Light", "source": "PHB 2024", "desc": ""}, {"name": "Trickery Domain", "shortName": "Trickery", "source": "PHB 2024", "desc": ""}, {"name": "War Domain", "shortName": "War", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Divine Order", "level": 1, "text": "You have dedicated yourself to one of the following sacred roles of your choice."}, {"name": "Protector", "level": 1, "text": "Trained for battle, you gain proficiency with Martial weapons and training with Heavy armor."}, {"name": "Spellcasting", "level": 1, "text": "You have learned to cast spells through prayer and meditation. See chapter 7|XPHB|7 for the rules on spellcasting. The information below details how you use those rules with Cleric spells, which appear on the Cleric spell list later in the class's description. Cantrips. You know three cantrips of your choice from the Cleric spell list. Guidance, Sacred Flame, and Thaumaturgy are recommended. Whenever you gain a Cleric level, you can replace one of your cantrips with another cantrip of your choice from the Cleric spell list. When you reach Cleric levels 4 and 10, you learn another cantrip of your choice from the Cleric spell list, as shown in the Cantrips column of the Cleric Features table. Spell Slots. The Cleric Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Cleric spell list. Bless, Cure Wounds, Guiding Bolt, and Shield of Faith are recommended. The number of spells on your list increases as you gain Cleric levels, as shown in the Prepared Spells column of the Cleric Features table. Whenever that number increases, choose additional spells from the Cleric spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots. For example, if you're a level 3 Cleric, your list of prepared spells can include six spells of levels 1 and 2 in any combination. If another Cleric feature gives you spells that you always have prepared, those spells don't count against the number of spells you can prepare with this feature, but those spells otherwise count as Cleric spells for you. Changing Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with other Cleric spells for which you have spell slots. Spellcasting Ability. Wisdom is your spellcasting ability for your Cleric spells. Spellcasting Focus. You can use a Holy Symbol as a Spellcasting Focus for your Cleric spells."}, {"name": "Thaumaturge", "level": 1, "text": "You know one extra cantrip from the Cleric spell list. In addition, your mystical connection to the divine gives you a bonus to your Intelligence (Arcana or Religion) checks. The bonus equals your Wisdom modifier (minimum of +1)."}, {"name": "Channel Divinity", "level": 2, "text": "You can channel divine energy directly from the Outer Planes to fuel magical effects. You start with two such effects: Divine Spark and Turn Undead, each of which is described below. Each time you use this class's Channel Divinity, choose which Channel Divinity effect from this class to create. You gain additional effect options at higher Cleric levels. You can use this class's Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain additional uses when you reach certain Cleric levels, as shown in the Channel Divinity column of the Cleric Features table. If a Channel Divinity effect requires a saving throw, the DC equals the spell save DC from this class's Spellcasting feature."}, {"name": "Divine Spark", "level": 2, "text": "As a Magic action, you point your Holy Symbol at another creature you can see within 30 feet of yourself and focus divine energy at it. Roll 1d8 and add your Wisdom modifier. You either restore Hit Points to the creature equal to that total or force the creature to make a Constitution saving throw. On a failed save, the creature takes Necrotic or Radiant damage (your choice) equal to that total. On a successful save, the creature takes half as much damage (round down). You roll an additional d8 when you reach Cleric levels 7 (2d8), 13 (3d8), and 18 (4d8)."}, {"name": "Turn Undead", "level": 2, "text": "As a Magic action, you present your Holy Symbol and censure Undead creatures. Each Undead of your choice within 30 feet of you must make a Wisdom saving throw. If the creature fails its save, it has the Frightened and Incapacitated conditions for 1 minute. For that duration, it tries to move as far from you as it can on its turns. This effect ends early on the creature if it takes any damage, if you have the Incapacitated condition, or if you die."}, {"name": "Cleric Subclass", "level": 3, "text": "You gain a Cleric subclass of your choice. A subclass is a specialization that grants you features at certain Cleric levels. For the rest of your career, you gain each of your subclass's features that are of your Cleric level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Cleric levels 8, 12, and 16."}, {"name": "Sear Undead", "level": 5, "text": "Whenever you use Turn Undead, you can roll a number of d8s equal to your Wisdom modifier (minimum of 1d8) and add the rolls together. Each Undead that fails its saving throw against that use of Turn Undead takes Radiant damage equal to the roll's total. This damage doesn't end the turn effect."}, {"name": "Subclass Feature", "level": 6, "text": "You gain a feature from your Cleric Subclass."}, {"name": "Blessed Strikes", "level": 7, "text": "Divine power infuses you in battle. You gain one of the following options of your choice (if you get either option from a Cleric subclass in an older book, use only the option you choose for this feature)."}, {"name": "Divine Strike", "level": 7, "text": "Once on each of your turns when you hit a creature with an attack roll using a weapon, you can cause the target to take an extra 1d8 Necrotic or Radiant damage (your choice)."}, {"name": "Potent Spellcasting", "level": 7, "text": "Add your Wisdom modifier to the damage you deal with any Cleric cantrip."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Divine Intervention", "level": 10, "text": "You can call on your deity or pantheon to intervene on your behalf. As a Magic action, choose any Cleric spell of level 5 or lower that doesn't require a Reaction to cast. As part of the same action, you cast that spell without expending a spell slot or needing Material components. You can't use this feature again until you finish a Long Rest."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Improved Blessed Strikes", "level": 14, "text": "The option you chose for Blessed Strikes grows more powerful. Divine Strike. The extra damage of your Divine Strike increases to 2d8. Potent Spellcasting. When you cast a Cleric cantrip and deal damage to a creature with it, you can give vitality to yourself or another creature within 60 feet of yourself, granting a number of Temporary Hit Points equal to twice your Wisdom modifier."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 17, "text": "You gain a feature from your Cleric Subclass."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Fate is recommended."}, {"name": "Greater Divine Intervention", "level": 20, "text": "You can call on even more powerful divine intervention. When you use your Divine Intervention feature, you can choose Wish when you select a spell. If you do so, you can't use Divine Intervention again until you finish 2d4 Long Rests."}]}, {"id": "druid", "name": "Druido", "originalName": "Druid", "source": "PHB 2024", "hitDie": "8", "image": "https://5e.tools/img/classes/XPHB/Druid.webp", "primaryAbility": ["WIS"], "proficiencies": ["Int", "Wis"], "tableLabels": ["Wild Shape", "Cantrips", "Prepared Spells", "1", "2", "3", "4", "5", "6", "7", "8", "9"], "progression": [{"level": 1, "values": ["0", "2", "4"]}, {"level": 2, "values": ["2", "2", "5"]}, {"level": 3, "values": ["2", "2", "6"]}, {"level": 4, "values": ["2", "3", "7"]}, {"level": 5, "values": ["2", "3", "9"]}, {"level": 6, "values": ["3", "3", "10"]}, {"level": 7, "values": ["3", "3", "11"]}, {"level": 8, "values": ["3", "3", "12"]}, {"level": 9, "values": ["3", "3", "14"]}, {"level": 10, "values": ["3", "4", "15"]}, {"level": 11, "values": ["3", "4", "16"]}, {"level": 12, "values": ["3", "4", "16"]}, {"level": 13, "values": ["3", "4", "17"]}, {"level": 14, "values": ["3", "4", "17"]}, {"level": 15, "values": ["3", "4", "18"]}, {"level": 16, "values": ["3", "4", "18"]}, {"level": 17, "values": ["4", "4", "19"]}, {"level": 18, "values": ["4", "4", "20"]}, {"level": 19, "values": ["4", "4", "21"]}, {"level": 20, "values": ["4", "4", "22"]}], "subclasses": [{"name": "Circle of the Land", "shortName": "Land", "source": "PHB 2024", "desc": ""}, {"name": "Circle of the Moon", "shortName": "Moon", "source": "PHB 2024", "desc": ""}, {"name": "Circle of the Sea", "shortName": "Sea", "source": "PHB 2024", "desc": ""}, {"name": "Circle of the Stars", "shortName": "Stars", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Druidic", "level": 1, "text": "You know Druidic, the secret language of Druids. While learning this ancient tongue, you also unlocked the magic of communicating with animals; you always have the Speak with Animals spell prepared. You can use Druidic to leave hidden messages. You and others who know Druidic automatically spot such a message. Others spot the message's presence with a successful 15 Intelligence (Investigation) check but can't decipher it without magic."}, {"name": "Magician", "level": 1, "text": "You know one extra cantrip from the Druid spell list. In addition, your mystical connection to nature gives you a bonus to your Intelligence (Arcana or Nature) checks. The bonus equals your Wisdom modifier (minimum bonus of +1)."}, {"name": "Primal Order", "level": 1, "text": "You have dedicated yourself to one of the following sacred roles of your choice."}, {"name": "Spellcasting", "level": 1, "text": "You have learned to cast spells through studying the mystical forces of nature. See chapter 7|XPHB|7 for the rules on spellcasting. The information below details how you use those rules with Druid spells, which appear on the Druid spell list later in the class's description. Cantrips. You know two cantrips of your choice from the Druid spell list. Druidcraft and Produce Flame are recommended. Whenever you gain a Druid level, you can replace one of your cantrips with another cantrip of your choice from the Druid spell list. When you reach Druid levels 4 and 10, you learn another cantrip of your choice from the Druid spell list, as shown in the Cantrips column of the Druid Features table. Spell Slots. The Druid Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose four level 1 spells from the Druid spell list. Animal Friendship, Cure Wounds, Faerie Fire, and Thunderwave are recommended. The number of spells on your list increases as you gain Druid levels, as shown in the Prepared Spells column of the Druid Features table. Whenever that number increases, choose additional spells from the Druid spell list until the number of spells on your list matches the number on the table. The chosen spells must be of a level for which you have spell slots. For example, if you're a level 3 Druid, your list of prepared spells can include six spells of levels 1 and 2 in any combination. If another Druid feature gives you spells that you always have prepared, those spells don't count against the number of spells you can prepare with this feature, but those spells otherwise count as Druid spells for you. Changing Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells with other Druid spells for which you have spell slots. Spellcasting Ability. Wisdom is your spellcasting ability for your Druid spells. Spellcasting Focus. You can use a Druidic Focus as a Spellcasting Focus for your Druid spells."}, {"name": "Warden", "level": 1, "text": "Trained for battle, you gain proficiency with Martial weapons and training with Medium armor."}, {"name": "Wild Companion", "level": 2, "text": "You can summon a nature spirit that assumes an animal form to aid you. As a Magic action, you can expend a spell slot or a use of Wild Shape to cast the Find Familiar spell without Material components. When you cast the spell in this way, the familiar is Fey and disappears when you finish a Long Rest."}, {"name": "Wild Shape", "level": 2, "text": "The power of nature allows you to assume the form of an animal. As a Bonus Action, you shape-shift into a Beast form that you have learned for this feature (see \"Known Forms\" below). You stay in that form for a number of hours equal to half your Druid level or until you use Wild Shape again, have the Incapacitated condition, or die. You can also leave the form early as a Bonus Action. Number of Uses. You can use Wild Shape twice. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain additional uses when you reach certain Druid levels, as shown in the Wild Shape column of the Druid Features table. Known Forms. You know four Beast forms for this feature, chosen from among Beast stat blocks that have a maximum Challenge Rating of 1/4 and that lack a Fly Speed (see appendix B for stat block options). The Rat, Riding Horse, Spider, and Wolf are recommended. Whenever you finish a Long Rest, you can replace one of your known forms with another eligible form. When you reach certain Druid levels, your number of known forms and the maximum Challenge Rating for those forms increases, as shown in the Beast Shapes table. In addition, starting at level 8, you can adopt a form that has a Fly Speed. When choosing known forms, you may look in the Monster Manual|XMM or elsewhere for eligible Beasts if the Dungeon Master permits you to do so.  Rules While Shape-Shifted. While in a form, you retain your personality, memories, and ability to speak, and the following rules apply: Temporary Hit Points. When you assume a Wild Shape form, you gain a number of Temporary Hit Points equal to your Druid level. Game Statistics. Your game statistics are replaced by the Beast's stat block, but you retain your creature type; Hit Points; Hit Point Dice; Intelligence, Wisdom, and Charisma scores; class features; languages; and feats. You also retain your skill and saving throw proficiencies and use your Proficiency for them, in addition to gaining the proficiencies of the creature. If a skill or saving throw modifier in the Beast's stat block is higher than yours, use the one in the stat block. No Spellcasting. You can't cast spells, but shape-shifting doesn't break your Concentration|XPHB or otherwise interfere with a spell you've already cast. Objects. Your ability to handle objects is determined by the form's limbs rather than your own. In addition, you choose whether your equipment falls in your space, merges into your new form, or is worn by it. Worn equipment functions as normal, but the DM decides whether it's practical for the new form to wear a piece of equipment based on the creature's size and shape. Your equipment doesn't change size or shape to match the new form, and any equipment that the new form can't wear must either fall to the ground or merge with the form. Equipment that merges with the form has no effect while you're in that form."}, {"name": "Druid Subclass", "level": 3, "text": "You gain a Druid subclass of your choice. A subclass is a specialization that grants you features at certain Druid levels. For the rest of your career, you gain each of your subclass's features that are of your Druid level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Druid levels 8, 12, and 16."}, {"name": "Wild Resurgence", "level": 5, "text": "Once on each of your turns, if you have no uses of Wild Shape left, you can give yourself one use by expending a spell slot (no action required). In addition, you can expend one use of Wild Shape (no action required) to give yourself a level 1 spell slot, but you can't do so again until you finish a Long Rest."}, {"name": "Subclass Feature", "level": 6, "text": "You gain a feature from your Druid Subclass."}, {"name": "Elemental Fury", "level": 7, "text": "The might of the elements flows through you. You gain one of the following options of your choice."}, {"name": "Potent Spellcasting", "level": 7, "text": "Add your Wisdom modifier to the damage you deal with any Druid cantrip."}, {"name": "Primal Strike", "level": 7, "text": "Once on each of your turns when you hit a creature with an attack roll using a weapon or a Beast form's attack in Wild Shape, you can cause the target to take an extra 1d8 Cold, Fire, Lightning, or Thunder damage (choose when you hit)."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 10, "text": "You gain a feature from your Druid Subclass."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 14, "text": "You gain a feature from your Druid Subclass."}, {"name": "Improved Elemental Fury", "level": 15, "text": "The option you chose for Elemental Fury grows more powerful, as detailed below. Potent Spellcasting. When you cast a Druid cantrip with a range of 10 feet or greater, the spell's range increases by 300 feet. Primal Strike. The extra damage of your Primal Strike increases to 2d8."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Beast Spells", "level": 18, "text": "While using Wild Shape, you can cast spells in Beast form, except for any spell that has a Material component with a cost specified or that consumes its Material component."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Dimensional Travel is recommended."}, {"name": "Archdruid", "level": 20, "text": "The vitality of nature constantly blooms within you, granting you the following benefits. Evergreen Wild Shape. Whenever you roll Initiative and have no uses of Wild Shape left, you regain one expended use of it. Nature Magician. You can convert uses of Wild Shape into a spell slot (no action required). Choose a number of your unexpended uses of Wild Shape and convert them into a single spell slot, with each use contributing 2 spell levels. For example, if you convert two uses of Wild Shape, you produce a level 4 spell slot. Once you use this benefit, you can't do so again until you finish a Long Rest. Longevity. The primal magic that you wield causes you to age more slowly. For every ten years that pass, your body ages only one year."}]}, {"id": "fighter", "name": "Guerriero", "originalName": "Fighter", "source": "PHB 2024", "hitDie": "10", "image": "https://5e.tools/img/classes/XPHB/Fighter.webp", "primaryAbility": ["STR", "DEX"], "proficiencies": ["Str", "Con"], "tableLabels": ["Second Wind", "Weapon Mastery"], "progression": [{"level": 1, "values": ["2", "3"]}, {"level": 2, "values": ["2", "3"]}, {"level": 3, "values": ["2", "3"]}, {"level": 4, "values": ["3", "4"]}, {"level": 5, "values": ["3", "4"]}, {"level": 6, "values": ["3", "4"]}, {"level": 7, "values": ["3", "4"]}, {"level": 8, "values": ["3", "4"]}, {"level": 9, "values": ["3", "4"]}, {"level": 10, "values": ["4", "5"]}, {"level": 11, "values": ["4", "5"]}, {"level": 12, "values": ["4", "5"]}, {"level": 13, "values": ["4", "5"]}, {"level": 14, "values": ["4", "5"]}, {"level": 15, "values": ["4", "5"]}, {"level": 16, "values": ["4", "6"]}, {"level": 17, "values": ["4", "6"]}, {"level": 18, "values": ["4", "6"]}, {"level": 19, "values": ["4", "6"]}, {"level": 20, "values": ["4", "6"]}], "subclasses": [{"name": "Battle Master", "shortName": "Battle Master", "source": "PHB 2024", "desc": ""}, {"name": "Champion", "shortName": "Champion", "source": "PHB 2024", "desc": ""}, {"name": "Eldritch Knight", "shortName": "Eldritch Knight", "source": "PHB 2024", "desc": ""}, {"name": "Psi Warrior", "shortName": "Psi Warrior", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Fighting Style", "level": 1, "text": "You have honed your martial prowess and gain a Fighting Style feat of your choice. Defense is recommended. Whenever you gain a Fighter level, you can replace the feat you chose with a different Fighting Style feat."}, {"name": "Second Wind", "level": 1, "text": "You have a limited well of physical and mental stamina that you can draw on. As a Bonus Action, you can use it to regain Hit Points equal to 1d10 plus your Fighter level. You can use this feature twice. You regain one expended use when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. When you reach certain Fighter levels, you gain more uses of this feature, as shown in the Second Wind column of the Fighter Features table."}, {"name": "Weapon Mastery", "level": 1, "text": "Your training with weapons allows you to use the weapon mastery properties of three kinds of Simple or Martial weapons of your choice. Whenever you finish a Long Rest, you can practice weapon drills and change one of those weapon choices. When you reach certain Fighter levels, you gain the ability to use the weapon mastery properties of more kinds of weapons, as shown in the Weapon Mastery column of the Fighter Features table."}, {"name": "Action Surge", "level": 2, "text": "You can push yourself beyond your normal limits for a moment. On your turn, you can take one additional action, except the Magic action. Once you use this feature, you can't do so again until you finish a Short Rest or Long Rest. Starting at level 17, you can use it twice before a rest but only once on a turn."}, {"name": "Tactical Mind", "level": 2, "text": "You have a mind for tactics on and off the battlefield. When you fail an ability check, you can expend a use of your Second Wind to push yourself toward success. Rather than regaining Hit Points, you roll 1d10 and add the number rolled to the ability check, potentially turning it into a success. If the check still fails, this use of Second Wind isn't expended."}, {"name": "Fighter Subclass", "level": 3, "text": "You gain a Fighter subclass of your choice. A subclass is a specialization that grants you features at certain Fighter levels. For the rest of your career, you gain each of your subclass's features that are of your Fighter level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Fighter levels 6, 8, 12, 14, and 16."}, {"name": "Extra Attack", "level": 5, "text": "You can attack twice instead of once whenever you take the Attack action on your turn."}, {"name": "Tactical Shift", "level": 5, "text": "Whenever you activate your Second Wind with a Bonus Action, you can move up to half your Speed without provoking Opportunity Attack."}, {"name": "Ability Score Improvement", "level": 6, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 7, "text": "You gain a feature from your Fighter Subclass."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Indomitable", "level": 9, "text": "If you fail a saving throw, you can reroll it with a bonus equal to your Fighter level. You must use the new roll, and you can't use this feature again until you finish a Long Rest. You can use this feature twice before a Long Rest starting at level 13 and three times before a Long Rest starting at level 17."}, {"name": "Tactical Master", "level": 9, "text": "When you attack with a weapon whose mastery property you can use, you can replace that property with the {@itemMastery Push|XPHB, {@itemMastery Sap|XPHB, or {@itemMastery Slow|XPHB property for that attack."}, {"name": "Subclass Feature", "level": 10, "text": "You gain a feature from your Fighter Subclass."}, {"name": "Two Extra Attacks", "level": 11, "text": "You can attack three times instead of once whenever you take the Attack action on your turn."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Indomitable", "level": 13, "text": "If you fail a saving throw, you can reroll it with a bonus equal to your Fighter level. You must use the new roll, and you can't use this feature again until you finish a Long Rest. You can use this feature twice before a Long Rest starting at level 13 and three times before a Long Rest starting at level 17."}, {"name": "Studied Attacks", "level": 13, "text": "You study your opponents and learn from each attack you make. If you make an attack roll against a creature and miss, you have Advantage on your next attack roll against that creature before the end of your next turn."}, {"name": "Ability Score Improvement", "level": 14, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 15, "text": "You gain a feature from your Fighter Subclass."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Action Surge", "level": 17, "text": "You can push yourself beyond your normal limits for a moment. On your turn, you can take one additional action, except the Magic action. Once you use this feature, you can't do so again until you finish a Short Rest or Long Rest. Starting at level 17, you can use it twice before a rest but only once on a turn."}, {"name": "Indomitable", "level": 17, "text": "If you fail a saving throw, you can reroll it with a bonus equal to your Fighter level. You must use the new roll, and you can't use this feature again until you finish a Long Rest. You can use this feature twice before a Long Rest starting at level 13 and three times before a Long Rest starting at level 17."}, {"name": "Subclass Feature", "level": 18, "text": "You gain a feature from your Fighter Subclass."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Combat Prowess is recommended."}, {"name": "Three Extra Attacks", "level": 20, "text": "You can attack four times instead of once whenever you take the Attack action on your turn."}]}, {"id": "monk", "name": "Monaco", "originalName": "Monk", "source": "PHB 2024", "hitDie": "8", "image": "https://5e.tools/img/classes/XPHB/Monk.webp", "primaryAbility": ["DEX", "WIS"], "proficiencies": ["Str", "Dex"], "tableLabels": ["Martial Arts", "Focus Points", "Unarmored Movement"], "progression": [{"level": 1, "values": ["—", "0", "0"]}, {"level": 2, "values": ["—", "2", "10"]}, {"level": 3, "values": ["—", "3", "10"]}, {"level": 4, "values": ["—", "4", "10"]}, {"level": 5, "values": ["—", "5", "10"]}, {"level": 6, "values": ["—", "6", "15"]}, {"level": 7, "values": ["—", "7", "15"]}, {"level": 8, "values": ["—", "8", "15"]}, {"level": 9, "values": ["—", "9", "15"]}, {"level": 10, "values": ["—", "10", "20"]}, {"level": 11, "values": ["—", "11", "20"]}, {"level": 12, "values": ["—", "12", "20"]}, {"level": 13, "values": ["—", "13", "20"]}, {"level": 14, "values": ["—", "14", "25"]}, {"level": 15, "values": ["—", "15", "25"]}, {"level": 16, "values": ["—", "16", "25"]}, {"level": 17, "values": ["—", "17", "25"]}, {"level": 18, "values": ["—", "18", "30"]}, {"level": 19, "values": ["—", "19", "30"]}, {"level": 20, "values": ["—", "20", "30"]}], "subclasses": [{"name": "Warrior of Mercy", "shortName": "Mercy", "source": "PHB 2024", "desc": ""}, {"name": "Warrior of Shadow", "shortName": "Shadow", "source": "PHB 2024", "desc": ""}, {"name": "Warrior of the Elements", "shortName": "Elements", "source": "PHB 2024", "desc": ""}, {"name": "Warrior of the Open Hand", "shortName": "Open Hand", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Bonus Unarmed Strike", "level": 1, "text": "You can make an Unarmed Strike as a Bonus Action."}, {"name": "Dexterous Attacks", "level": 1, "text": "You can use your Dexterity modifier instead of your Strength modifier for the attack and damage rolls of your Unarmed Strikes and Monk weapons. In addition, when you use the Grapple or Shove option of your Unarmed Strike, you can use your Dexterity modifier instead of your Strength modifier to determine the save DC."}, {"name": "Martial Arts", "level": 1, "text": "Your practice of martial arts gives you mastery of combat styles that use your Unarmed Strike and Monk weapons, which are the following: Simple Melee Weapons Martial Melee Weapons that have the Light property You gain the following benefits while you are unarmed or wielding only Monk weapons and you aren't wearing armor or wielding a Shield."}, {"name": "Martial Arts Die", "level": 1, "text": "You can roll 1d6 in place of the normal damage of your Unarmed Strike or Monk weapons. This die changes as you gain Monk levels, as shown in the Martial Arts column of the Monk Features table."}, {"name": "Unarmored Defense", "level": 1, "text": "While you aren't wearing armor or wielding a Shield, your base Armor Class equals 10 plus your Dexterity and Wisdom modifiers."}, {"name": "Flurry of Blows", "level": 2, "text": "You can expend 1 Focus Point to make two Unarmed Strikes as a Bonus Action."}, {"name": "Monk's Focus", "level": 2, "text": "Your focus and martial training allow you to harness a well of extraordinary energy within yourself. This energy is represented by Focus Points. Your Monk level determines the number of points you have, as shown in the Focus Points column of the Monk Features table. You can expend these points to enhance or fuel certain Monk features. You start knowing three such features: Flurry of Blows, Patient Defense, and Step of the Wind, each of which is detailed below. When you expend a Focus Point, it is unavailable until you finish a Short Rest or Long Rest, at the end of which you regain all your expended points. Some features that use Focus Points require your target to make a saving throw. The save DC equals 8 plus your Wisdom modifier and Proficiency."}, {"name": "Patient Defense", "level": 2, "text": "You can take the Disengage action as a Bonus Action. Alternatively, you can expend 1 Focus Point to take both the Disengage and the Dodge actions as a Bonus Action."}, {"name": "Step of the Wind", "level": 2, "text": "You can take the Dash action as a Bonus Action. Alternatively, you can expend 1 Focus Point to take both the Disengage and Dash actions as a Bonus Action, and your jump distance is doubled for the turn."}, {"name": "Unarmored Movement", "level": 2, "text": "Your speed increases by 10 feet while you aren't wearing armor or wielding a Shield. This bonus increases when you reach certain Monk levels, as shown on the Monk Features table."}, {"name": "Uncanny Metabolism", "level": 2, "text": "When you roll Initiative, you can regain all expended Focus Points. When you do so, roll your Martial Arts die, and regain a number of Hit Points equal to your Monk level plus the number rolled. Once you use this feature, you can't use it again until you finish a Long Rest."}, {"name": "Deflect Attacks", "level": 3, "text": "When an attack roll hits you and its damage includes Bludgeoning, Piercing, or Slashing damage, you can take a Reaction to reduce the attack's total damage against you. The reduction equals 1d10 plus your Dexterity modifier and Monk level. If you reduce the damage to 0, you can expend 1 Focus Point to redirect some of the attack's force. If you do so, choose a creature you can see within 5 feet of yourself if the attack was a melee attack or a creature you can see within 60 feet of yourself that isn't behind Cover if the attack was a ranged attack. That creature must succeed on a Dexterity saving throw or take damage equal to two rolls of your Martial Arts die plus your Dexterity modifier. The damage is the same type dealt by the attack."}, {"name": "Monk Subclass", "level": 3, "text": "You gain a Monk subclass of your choice. A subclass is a specialization that grants you features at certain Monk levels. For the rest of your career, you gain each of your subclass's features that are of your Monk level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Monk levels 8, 12, and 16."}, {"name": "Slow Fall", "level": 4, "text": "You can take a Reaction when you fall to reduce any damage you take from the fall by an amount equal to five times your Monk level."}, {"name": "Extra Attack", "level": 5, "text": "You can attack twice instead of once whenever you take the Attack action on your turn."}, {"name": "Stunning Strike", "level": 5, "text": "Once per turn when you hit a creature with a Monk weapon or an Unarmed Strike, you can expend 1 Focus Point to attempt a stunning strike. The target must make a Constitution saving throw. On a failed save, the target has the Stunned condition until the start of your next turn. On a successful save, the target's Speed is halved until the start of your next turn, and the next attack roll made against the target before then has Advantage."}, {"name": "Empowered Strikes", "level": 6, "text": "Whenever you deal damage with your Unarmed Strike, it can deal your choice of Force damage or its normal damage type."}, {"name": "Subclass Feature", "level": 6, "text": "You gain a feature from your Monk subclass."}, {"name": "Evasion", "level": 7, "text": "When you're subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail. You don't benefit from this feature if you have the Incapacitated condition."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Acrobatic Movement", "level": 9, "text": "While you aren't wearing armor or wielding a Shield, you gain the ability to move along vertical surfaces and across liquids on your turn without falling during the movement."}, {"name": "Heightened Focus", "level": 10, "text": "Your Flurry of Blows, Patient Defense, and Step of the Wind gain the following benefits. . Flurry of Blows. You can expend 1 Focus Point to use Flurry of Blows and make three Unarmed Strikes with it instead of two. Patient Defense. When you expend a Focus Point to use Patient Defense, you gain a number of Temporary Hit Points equal to two rolls of your Martial Arts die. Step of the Wind. When you expend a Focus Point to use Step of the Wind, you can choose a willing creature within 5 feet of yourself that is Large or smaller. You move the creature with you until the end of your turn. The creature's movement doesn't provoke Opportunity Attack."}, {"name": "Self-Restoration", "level": 10, "text": "Through sheer force of will, you can remove one of the following conditions from yourself at the end of each of your turns: Charmed, Frightened, or Poisoned. In addition, forgoing food and drink doesn't give you levels of Exhaustion."}, {"name": "Subclass Feature", "level": 11, "text": "You gain a feature from your Monk subclass."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Deflect Energy", "level": 13, "text": "You can now use your Deflect Attacks feature against attacks that deal any damage type, not just Bludgeoning, Piercing, or Slashing."}, {"name": "Disciplined Survivor", "level": 14, "text": "Your physical and mental discipline grant you proficiency in all saving throws. Additionally, whenever you make a saving throw and fail, you can expend 1 Focus Point to reroll it, and you must use the new roll."}, {"name": "Perfect Focus", "level": 15, "text": "When you roll Initiative and don't use Uncanny Metabolism, you regain expended Focus Points until you have 4 if you have 3 or fewer."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 17, "text": "You gain a feature from your Monk subclass."}, {"name": "Superior Defense", "level": 18, "text": "At the start of your turn, you can expend 3 Focus Points to bolster yourself against harm for 1 minute or until you have the Incapacitated condition. During that time, you have Resistance to all damage except Force damage."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Irresistible Offense is recommended."}, {"name": "Body and Mind", "level": 20, "text": "You have developed your body and mind to new heights. Your Dexterity and Wisdom scores increase by 4, to a maximum of 25."}]}, {"id": "paladin", "name": "Paladino", "originalName": "Paladin", "source": "PHB 2024", "hitDie": "10", "image": "https://5e.tools/img/classes/XPHB/Paladin.webp", "primaryAbility": ["STR", "CHA"], "proficiencies": ["Wis", "Cha"], "tableLabels": ["Channel Divinity", "Prepared Spells", "1", "2", "3", "4", "5"], "progression": [{"level": 1, "values": ["0", "2"]}, {"level": 2, "values": ["0", "3"]}, {"level": 3, "values": ["2", "4"]}, {"level": 4, "values": ["2", "5"]}, {"level": 5, "values": ["2", "6"]}, {"level": 6, "values": ["2", "6"]}, {"level": 7, "values": ["2", "7"]}, {"level": 8, "values": ["2", "7"]}, {"level": 9, "values": ["2", "9"]}, {"level": 10, "values": ["2", "9"]}, {"level": 11, "values": ["3", "10"]}, {"level": 12, "values": ["3", "10"]}, {"level": 13, "values": ["3", "11"]}, {"level": 14, "values": ["3", "11"]}, {"level": 15, "values": ["3", "12"]}, {"level": 16, "values": ["3", "12"]}, {"level": 17, "values": ["3", "14"]}, {"level": 18, "values": ["3", "14"]}, {"level": 19, "values": ["3", "15"]}, {"level": 20, "values": ["3", "15"]}], "subclasses": [{"name": "Oath of Devotion", "shortName": "Devotion", "source": "PHB 2024", "desc": ""}, {"name": "Oath of Glory", "shortName": "Glory", "source": "PHB 2024", "desc": ""}, {"name": "Oath of the Ancients", "shortName": "Ancients", "source": "PHB 2024", "desc": ""}, {"name": "Oath of Vengeance", "shortName": "Vengeance", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Lay on Hands", "level": 1, "text": "Your blessed touch can heal wounds. You have a pool of healing power that replenishes when you finish a Long Rest. With that pool, you can restore a total number of Hit Points equal to five times your Paladin level. As a Bonus Action, you can touch a creature (which could be yourself) and draw power from the pool of healing to restore a number of Hit Points to that creature, up to the maximum amount remaining in the pool. You can also expend 5 Hit Points from the pool of healing power to remove the Poisoned condition from the creature; those points don't also restore Hit Points to the creature."}, {"name": "Spellcasting", "level": 1, "text": "You have learned to cast spells through prayer and meditation. See chapter 7|XPHB|7 for the rules on spellcasting. The information below details how you use those rules with Paladin spells, which appear in the Paladin spell list later in the class's description. Spell Slots. The Paladin Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Paladin spells. Heroism and Searing Smite are recommended. The number of spells on your list increases as you gain Paladin levels, as shown in the Prepared Spells column of the Paladin Features table. Whenever that number increases, choose additional Paladin spells until the number of spells on your list matches the number in the Paladin Features table. The chosen spells must be of a level for which you have spell slots. For example, if you're a level 5 Paladin, your list of prepared spells can include six Paladin spells of level 1 or 2 in any combination. If another Paladin feature gives you spells that you always have prepared, those spells don't count against the number of spells you can prepare with this feature, but those spells otherwise count as Paladin spells for you. Changing Your Prepared Spells. Whenever you finish a Long Rest, you can replace one spell on your list with another Paladin spell for which you have spell slots. Spellcasting Ability. Charisma is your spellcasting ability for your Paladin spells. Spellcasting Focus. You can use a Holy Symbol as a Spellcasting Focus for your Paladin spells."}, {"name": "Weapon Mastery", "level": 1, "text": "Your training with weapons allows you to use the weapon mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longsword and Javelin. Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the weapon mastery properties of Halberd and Flail."}, {"name": "Fighting Style", "level": 2, "text": "You gain a Fighting Style feat of your choice. Instead of choosing one of those feats, you can choose the option below."}, {"name": "Paladin's Smite", "level": 2, "text": "You always have the Divine Smite spell prepared. In addition, you can cast it without expending a spell slot, but you must finish a Long Rest before you can cast it in this way again."}, {"name": "Channel Divinity", "level": 3, "text": "You can channel divine energy directly from the Outer Planes, using it to fuel magical effects. You start with one such effect: Divine Sense, which is described below. Other Paladin features give additional Channel Divinity effect options. Each time you use this class's Channel Divinity, you choose which effect from this class to create. You can use this class's Channel Divinity twice. You regain one of its expended uses when you finish a Short Rest, and you regain all expended uses when you finish a Long Rest. You gain an additional use when you reach Paladin level 11. If a Channel Divinity effect requires a saving throw, the DC equals the spell save DC from this class's Spellcasting feature."}, {"name": "Divine Sense", "level": 3, "text": "As a Bonus Action, you can open your awareness to detect Celestials, Fiends, and Undead. For the next 10 minutes or until you have the Incapacitated condition, you know the location of any creature of those types within 60 feet of yourself, and you know its creature type. Within the same radius, you also detect the presence of any place or object that has been consecrated or desecrated, as with the Hallow spell."}, {"name": "Paladin Subclass", "level": 3, "text": "You gain a Paladin subclass of your choice. A subclass is a specialization that grants you features at certain Paladin levels. For the rest of your career, you gain each of your subclass's features that are of your Paladin level or lower. Breaking Your Oath. A Paladin tries to hold to the highest standards of conduct, but even the most dedicated are fallible. Sometimes a Paladin transgresses their oath. A Paladin who has broken a vow typically seeks absolution, spending an all-night vigil as a sign of penitence or undertaking a fast. After a rite of forgiveness, the Paladin starts fresh. If your Paladin unrepentantly violates their oath, talk to your DM. Your Paladin should probably take a more appropriate subclass or even abandon the class and adopt another one."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Paladin levels 8, 12, and 16."}, {"name": "Extra Attack", "level": 5, "text": "You can attack twice instead of once whenever you take the Attack action on your turn."}, {"name": "Faithful Steed", "level": 5, "text": "You can call on the aid of an otherworldly steed. You always have the Find Steed spell prepared. You can also cast the spell once without expending a spell slot, and you regain the ability to do so when you finish a Long Rest."}, {"name": "Aura of Protection", "level": 6, "text": "You radiate a protective, unseeable aura in a 10-foot Emanation [Area of Effect] that originates from you. The aura is inactive while you have the Incapacitated condition. You and your allies in the aura gain a bonus to saving throws equal to your Charisma modifier (minimum bonus of +1). If another Paladin is present, a creature can benefit from only one Aura of Protection at a time; the creature chooses which aura while in them."}, {"name": "Subclass Feature", "level": 7, "text": "You gain a feature from your Paladin Subclass."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Abjure Foes", "level": 9, "text": "As a Magic action, you can expend one use of this class's Channel Divinity to overwhelm foes with awe. As you present your Holy Symbol or weapon, you can target a number of creatures equal to your Charisma modifier (minimum of one creature) that you can see within 60 feet of yourself. Each target must succeed on a Wisdom saving throw or have the Frightened condition for 1 minute or until it takes any damage. While Frightened in this way, a target can do only one of the following on its turns: move, take an action, or take a Bonus Action."}, {"name": "Aura of Courage", "level": 10, "text": "You and your allies have Immunity to the Frightened condition while in your Aura of Protection. If a Frightened ally enters the aura, that condition has no effect on that ally while there."}, {"name": "Radiant Strikes", "level": 11, "text": "Your strikes now carry supernatural power. When you hit a target with an attack roll using a Melee weapon or an Unarmed Strike, the target takes an extra 1d8 Radiant damage."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Restoring Touch", "level": 14, "text": "When you use Lay On Hands on a creature, you can also remove one or more of the following conditions from the creature: Blinded, Charmed, Deafened, Frightened, Paralyzed, or Stunned. You must expend 5 Hit Points from the healing pool of Lay On Hands for each of these conditions you remove; those points don't also restore Hit Points to the creature."}, {"name": "Subclass Feature", "level": 15, "text": "You gain a feature from your Paladin Subclass."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Aura Expansion", "level": 18, "text": "Your Aura of Protection is now a 30-foot Emanation [Area of Effect]."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Truesight is recommended."}, {"name": "Subclass Feature", "level": 20, "text": "You gain a feature from your Paladin Subclass."}]}, {"id": "ranger", "name": "Ranger", "originalName": "Ranger", "source": "PHB 2024", "hitDie": "10", "image": "https://5e.tools/img/classes/XPHB/Ranger.webp", "primaryAbility": ["DEX", "WIS"], "proficiencies": ["Str", "Dex"], "tableLabels": ["Favored Enemy", "Prepared Spells", "1", "2", "3", "4", "5"], "progression": [{"level": 1, "values": ["2", "2"]}, {"level": 2, "values": ["2", "3"]}, {"level": 3, "values": ["2", "4"]}, {"level": 4, "values": ["2", "5"]}, {"level": 5, "values": ["3", "6"]}, {"level": 6, "values": ["3", "6"]}, {"level": 7, "values": ["3", "7"]}, {"level": 8, "values": ["3", "7"]}, {"level": 9, "values": ["4", "9"]}, {"level": 10, "values": ["4", "9"]}, {"level": 11, "values": ["4", "10"]}, {"level": 12, "values": ["4", "10"]}, {"level": 13, "values": ["5", "11"]}, {"level": 14, "values": ["5", "11"]}, {"level": 15, "values": ["5", "12"]}, {"level": 16, "values": ["5", "12"]}, {"level": 17, "values": ["6", "14"]}, {"level": 18, "values": ["6", "14"]}, {"level": 19, "values": ["6", "15"]}, {"level": 20, "values": ["6", "15"]}], "subclasses": [{"name": "Beast Master", "shortName": "Beast Master", "source": "PHB 2024", "desc": ""}, {"name": "Fey Wanderer", "shortName": "Fey Wanderer", "source": "PHB 2024", "desc": ""}, {"name": "Gloom Stalker", "shortName": "Gloom Stalker", "source": "PHB 2024", "desc": ""}, {"name": "Hunter", "shortName": "Hunter", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Favored Enemy", "level": 1, "text": "You always have the Hunter's Mark spell prepared. You can cast it twice without expending a spell slot, and you regain all expended uses of this ability when you finish a Long Rest. The number of times you can cast the spell without a spell slot increases when you reach certain Ranger levels, as shown in the Favored Enemy column of the Ranger Features table."}, {"name": "Spellcasting", "level": 1, "text": "You have learned to channel the magical essence of nature to cast spells. See chapter 7|XPHB|7 for the rules on spellcasting. The information below details how you use those rules with Ranger spells, which appear in the Ranger spell list later in the class's description. Spell Slots. The Ranger Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Ranger spells. Cure Wounds and Ensnaring Strike are recommended. The number of spells on your list increases as you gain Ranger levels, as shown in the Prepared Spells column of the Ranger Features table. Whenever that number increases, choose additional Ranger spells until the number of spells on your list matches the number in the Ranger Features table. The chosen spells must be of a level for which you have spell slots. For example, if you're a level 5 Ranger, your list of prepared spells can include six Ranger spells of level 1 or 2 in any combination. If another Ranger feature gives you spells that you always have prepared, those spells don't count against the number of spells you can prepare with this feature, but those spells otherwise count as Ranger spells for you. Changing Your Prepared Spells. Whenever you finish a Long Rest, you can replace one spell on your list with another Ranger spell for which you have spell slots. Spellcasting Ability. Wisdom is your spellcasting ability for your Ranger spells. Spellcasting Focus. You can use a Druidic Focus as a Spellcasting Focus for your Ranger spells."}, {"name": "Weapon Mastery", "level": 1, "text": "Your training with weapons allows you to use the weapon mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Longbow and Shortsword. Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the weapon mastery properties of Scimitar and Longsword."}, {"name": "Deft Explorer", "level": 2, "text": "Thanks to your travels, you gain the following benefits. Expertise. Choose one of your skill proficiencies with which you lack Expertise. You gain Expertise in that skill. Languages. You know two languages of your choice from the language tables in chapter 2|XPHB|2|Choose Languages."}, {"name": "Fighting Style", "level": 2, "text": "You gain a Fighting Style feat of your choice. Instead of choosing one of those feats, you can choose the option below."}, {"name": "Ranger Subclass", "level": 3, "text": "You gain a Ranger subclass of your choice. A subclass is a specialization that grants you features at certain Ranger levels. For the rest of your career, you gain each of your subclass's features that are of your Ranger level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Ranger levels 8, 12, and 16."}, {"name": "Extra Attack", "level": 5, "text": "You can attack twice instead of once whenever you take the Attack action on your turn."}, {"name": "Roving", "level": 6, "text": "Your Speed increases by 10 feet while you aren't wearing Heavy armor. You also have a Climb Speed and a Swim Speed equal to your Speed."}, {"name": "Subclass Feature", "level": 7, "text": "You gain a feature from your Ranger Subclass."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Expertise", "level": 9, "text": "Choose two of your skill proficiencies with which you lack Expertise. You gain Expertise in those skills."}, {"name": "Tireless", "level": 10, "text": "Primal forces now help fuel you on your journeys, granting you the following benefits. Temporary Hit Points. As a Magic action, you can give yourself a number of Temporary Hit Points equal to 1d8 plus your Wisdom modifier (minimum of 1). You can use this action a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest. Decrease Exhaustion. Whenever you finish a Short Rest, your Exhaustion level, if any, decreases by 1."}, {"name": "Subclass Feature", "level": 11, "text": "You gain a feature from your Ranger Subclass."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Relentless Hunter", "level": 13, "text": "Taking damage can't break your Concentration|XPHB on Hunter's Mark."}, {"name": "Nature's Veil", "level": 14, "text": "You invoke spirits of nature to magically hide yourself. As a Bonus Action, you can give yourself the Invisible condition until the end of your next turn. You can use this feature a number of times equal to your Wisdom modifier (minimum of once), and you regain all expended uses when you finish a Long Rest."}, {"name": "Subclass Feature", "level": 15, "text": "You gain a feature from your Ranger Subclass."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Precise Hunter", "level": 17, "text": "You have Advantage on attack rolls against the creature currently marked by your Hunter's Mark."}, {"name": "Feral Senses", "level": 18, "text": "Your connection to the forces of nature grants you Blindsight with a range of 30 feet."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Dimensional Travel is recommended."}, {"name": "Foe Slayer", "level": 20, "text": "The damage die of your Hunter's Mark is a d10 rather than a d6."}]}, {"id": "rogue", "name": "Ladro", "originalName": "Rogue", "source": "PHB 2024", "hitDie": "8", "image": "https://5e.tools/img/classes/XPHB/Rogue.webp", "primaryAbility": ["DEX"], "proficiencies": ["Dex", "Int"], "tableLabels": ["Sneak Attack"], "progression": [{"level": 1, "values": ["—"]}, {"level": 2, "values": ["—"]}, {"level": 3, "values": ["—"]}, {"level": 4, "values": ["—"]}, {"level": 5, "values": ["—"]}, {"level": 6, "values": ["—"]}, {"level": 7, "values": ["—"]}, {"level": 8, "values": ["—"]}, {"level": 9, "values": ["—"]}, {"level": 10, "values": ["—"]}, {"level": 11, "values": ["—"]}, {"level": 12, "values": ["—"]}, {"level": 13, "values": ["—"]}, {"level": 14, "values": ["—"]}, {"level": 15, "values": ["—"]}, {"level": 16, "values": ["—"]}, {"level": 17, "values": ["—"]}, {"level": 18, "values": ["—"]}, {"level": 19, "values": ["—"]}, {"level": 20, "values": ["—"]}], "subclasses": [{"name": "Arcane Trickster", "shortName": "Arcane Trickster", "source": "PHB 2024", "desc": ""}, {"name": "Assassin", "shortName": "Assassin", "source": "PHB 2024", "desc": ""}, {"name": "Soulknife", "shortName": "Soulknife", "source": "PHB 2024", "desc": ""}, {"name": "Thief", "shortName": "Thief", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Expertise", "level": 1, "text": "You gain Expertise in two of your skill proficiencies of your choice. Sleight of Hand and Stealth are recommended if you have proficiency in them. At Rogue level 6, you gain Expertise in two more of your skill proficiencies of your choice."}, {"name": "Sneak Attack", "level": 1, "text": "You know how to strike subtly and exploit a foe's distraction. Once per turn, you can deal an extra 1d6 damage to one creature you hit with an attack roll if you have Advantage on the roll and the attack uses a Finesse or a Ranged weapon. The extra damage's type is the same as the weapon's type. You don't need Advantage on the attack roll if at least one of your allies is within 5 feet of the target, the ally doesn't have the Incapacitated condition, and you don't have Disadvantage on the attack roll. The extra damage increases as you gain Rogue levels, as shown in the Sneak Attack column of the Rogue Features table."}, {"name": "Thieves' Cant", "level": 1, "text": "You picked up various languages in the communities where you plied your roguish talents. You know Thieves' Cant and one other language of your choice, which you choose from the language tables in chapter 2|XPHB|2|Choose Languages."}, {"name": "Weapon Mastery", "level": 1, "text": "Your training with weapons allows you to use the weapon mastery properties of two kinds of weapons of your choice with which you have proficiency, such as Dagger and Shortbow. Whenever you finish a Long Rest, you can change the kinds of weapons you chose. For example, you could switch to using the weapon mastery properties of Scimitar and Shortsword."}, {"name": "Cunning Action", "level": 2, "text": "Your quick thinking and agility allow you to move and act quickly. On your turn, you can take one of the following actions as a Bonus Action: Dash, Disengage, or Hide."}, {"name": "Rogue Subclass", "level": 3, "text": "You gain a Rogue subclass of your choice. A subclass is a specialization that grants you features at certain Rogue levels. For the rest of your career, you gain each of your subclass's features that are of your Rogue level or lower."}, {"name": "Steady Aim", "level": 3, "text": "As a Bonus Action, you give yourself Advantage on your next attack roll on the current turn. You can use this feature only if you haven't moved during this turn, and after you use it, your Speed is 0 until the end of the current turn."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Rogue levels 8, 10, 12, and 16."}, {"name": "Cunning Strike", "level": 5, "text": "You've developed cunning ways to use your Sneak Attack. When you deal Sneak Attack damage, you can add one of the following Cunning Strike effects. Each effect has a die cost, which is the number of Sneak Attack damage dice you must forgo to add the effect. You remove the die before rolling, and the effect occurs immediately after the attack's damage is dealt. For example, if you add the Poison effect, remove 1d6 from the Sneak Attack's damage before rolling. If a Cunning Strike effect requires a saving throw, the DC equals 8 plus your Dexterity modifier and Proficiency."}, {"name": "Poison (Cost: 1d6)", "level": 5, "text": "You add a toxin to your strike, forcing the target to make a Constitution saving throw. On a failed save, the target has the Poisoned condition for 1 minute. At the end of each of its turns, the Poisoned target repeats the save, ending the effect on itself on a success. To use this effect, you must have a Poisoner's Kit on your person."}, {"name": "Trip (Cost: 1d6)", "level": 5, "text": "If the target is Large or smaller, it must succeed on a Dexterity saving throw or have the Prone condition."}, {"name": "Uncanny Dodge", "level": 5, "text": "When an attacker that you can see hits you with an attack roll, you can take a Reaction to halve the attack's damage against you (round down)."}, {"name": "Withdraw (Cost: 1d6)", "level": 5, "text": "Immediately after the attack, you move up to half your Speed without provoking Opportunity Attack."}, {"name": "Expertise", "level": 6, "text": "You gain Expertise in two of your Skill Proficiencies of your choice."}, {"name": "Evasion", "level": 7, "text": "You can nimbly dodge out of the way of certain dangers. When you're subjected to an effect that allows you to make a Dexterity saving throw to take only half damage, you instead take no damage if you succeed on the saving throw and only half damage if you fail. You can't use this feature if you have the Incapacitated condition."}, {"name": "Reliable Talent", "level": 7, "text": "Whenever you make an ability check that uses one of your skill or tool proficiencies, you can treat a d20 roll of 9 or lower as a 10."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 9, "text": "You gain a feature from your Rogue Subclass."}, {"name": "Ability Score Improvement", "level": 10, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Improved Cunning Strike", "level": 11, "text": "You can use up to two Cunning Strike effects when you deal Sneak Attack damage, paying the die cost for each effect."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 13, "text": "You gain a feature from your Rogue Subclass."}, {"name": "Daze (Cost: 2d6)", "level": 14, "text": "The target must succeed on a Constitution saving throw, or on its next turn, it can do only one of the following: move or take an action or a Bonus Action."}, {"name": "Devious Strikes", "level": 14, "text": "You've practiced new ways to use your Sneak Attack deviously. The following effects are now among your Cunning Strike options."}, {"name": "Knock Out (Cost: 6d6)", "level": 14, "text": "The target must succeed on a Constitution saving throw, or it has the Unconscious condition for 1 minute or until it takes any damage. The Unconscious target repeats the save at the end of each of its turns, ending the effect on itself on a success."}, {"name": "Obscure (Cost: 3d6)", "level": 14, "text": "The target must succeed on a Dexterity saving throw, or it has the Blinded condition until the end of its next turn."}, {"name": "Slippery Mind", "level": 15, "text": "Your cunning mind is exceptionally difficult to control. You gain proficiency in Wisdom and Charisma saving throws."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 17, "text": "You gain a feature from your Rogue Subclass."}, {"name": "Elusive", "level": 18, "text": "You're so evasive that attackers rarely gain the upper hand against you. No attack roll can have Advantage against you unless you have the Incapacitated condition."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of the Night Spirit is recommended."}, {"name": "Stroke of Luck", "level": 20, "text": "You have a marvelous knack for succeeding when you need to. If you fail a D20 Test, you can turn the roll into a 20. Once you use this feature, you can't use it again until you finish a Short Rest or Long Rest."}]}, {"id": "sorcerer", "name": "Stregone", "originalName": "Sorcerer", "source": "PHB 2024", "hitDie": "6", "image": "https://5e.tools/img/classes/XPHB/Sorcerer.webp", "primaryAbility": ["CHA"], "proficiencies": ["Con", "Cha"], "tableLabels": ["Sorcery Points", "Cantrips", "Prepared Spells", "1", "2", "3", "4", "5", "6", "7", "8", "9"], "progression": [{"level": 1, "values": ["0", "4", "2"]}, {"level": 2, "values": ["2", "4", "4"]}, {"level": 3, "values": ["3", "4", "6"]}, {"level": 4, "values": ["4", "5", "7"]}, {"level": 5, "values": ["5", "5", "9"]}, {"level": 6, "values": ["6", "5", "10"]}, {"level": 7, "values": ["7", "5", "11"]}, {"level": 8, "values": ["8", "5", "12"]}, {"level": 9, "values": ["9", "5", "14"]}, {"level": 10, "values": ["10", "6", "15"]}, {"level": 11, "values": ["11", "6", "16"]}, {"level": 12, "values": ["12", "6", "16"]}, {"level": 13, "values": ["13", "6", "17"]}, {"level": 14, "values": ["14", "6", "17"]}, {"level": 15, "values": ["15", "6", "18"]}, {"level": 16, "values": ["16", "6", "18"]}, {"level": 17, "values": ["17", "6", "19"]}, {"level": 18, "values": ["18", "6", "20"]}, {"level": 19, "values": ["19", "6", "21"]}, {"level": 20, "values": ["20", "6", "22"]}], "subclasses": [{"name": "Aberrant Sorcery", "shortName": "Aberrant", "source": "PHB 2024", "desc": ""}, {"name": "Clockwork Sorcery", "shortName": "Clockwork", "source": "PHB 2024", "desc": ""}, {"name": "Draconic Sorcery", "shortName": "Draconic", "source": "PHB 2024", "desc": ""}, {"name": "Wild Magic Sorcery", "shortName": "Wild Magic", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Innate Sorcery", "level": 1, "text": "An event in your past left an indelible mark on you, infusing you with simmering magic. As a Bonus Action, you can unleash that magic for 1 minute, during which you gain the following benefits: The spell save DC of your Sorcerer spells increases by 1. You have Advantage on the attack rolls of Sorcerer spells you cast. You can use this feature twice, and you regain all expended uses of it when you finish a Long Rest."}, {"name": "Spellcasting", "level": 1, "text": "Drawing from your innate magic, you can cast spells. See chapter 7|XPHB|7 for the rules on spellcasting. The information below details how you use those rules with Sorcerer spells, which appear in the Sorcerer spell list later in the class's description. Cantrips. You know four Sorcerer cantrips of your choice. Light, Prestidigitation, Shocking Grasp, and Sorcerous Burst are recommended. Whenever you gain a Sorcerer level, you can replace one of your cantrips from this feature with another Sorcerer cantrip of your choice. When you reach Sorcerer levels 4 and 10, you learn another Sorcerer cantrip of your choice, as shown in the Cantrips column of the Sorcerer Features table. Spell Slots. The Sorcerer Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Sorcerer spells. Burning Hands and Detect Magic are recommended. The number of spells on your list increases as you gain Sorcerer levels, as shown in the Prepared Spells column of the Sorcerer Features table. Whenever that number increases, choose additional Sorcerer spells until the number of spells on your list matches the number in the Sorcerer Features table. The chosen spells must be of a level for which you have spell slots. For example, if you're a level 3 Sorcerer, your list of prepared spells can include six Sorcerer spells of level 1 or 2 in any combination. If another Sorcerer feature gives you spells that you always have prepared, those spells don't count against the number of spells you can prepare with this feature, but those spells otherwise count as Sorcerer spells for you. Changing Your Prepared Spells. Whenever you gain a Sorcerer level, you can replace one spell on your list with another Sorcerer spell for which you have spell slots. Spellcasting Ability. Charisma is your spellcasting ability for your Sorcerer spells. Spellcasting Focus. You can use an Arcane Focus as a Spellcasting Focus for your Sorcerer spells."}, {"name": "Font of Magic", "level": 2, "text": "You can tap into the wellspring of magic within yourself. This wellspring is represented by Sorcery Points, which allow you to create a variety of magical effects. You have 2 Sorcery Points, and you gain more as you reach higher levels, as shown in the Sorcery Points column of the Sorcerer Features table. You can't have more Sorcery Points than the number shown in the table for your level. You regain all expended Sorcery Points when you finish a Long Rest. You can use your Sorcery Points to fuel the options below, along with other features, such as Metamagic, that use those points. Converting Spell Slots to Sorcery Points. You can expend a spell slot to gain a number of Sorcery Points equal to the slot's level (no action required). Creating Spell Slots. As a Bonus Action, you can transform unexpended Sorcery Points into one spell slot. The Creating Spell Slots table shows the cost of creating a spell slot of a given level, and it lists the minimum Sorcerer level you must be to create a slot. You can create a spell slot no higher than level 5. Any spell slot you create with this feature vanishes when you finish a Long Rest."}, {"name": "Metamagic", "level": 2, "text": "Because your magic flows from within, you can alter your spells to suit your needs; you gain two Metamagic options of your choice from \"Metamagic Options\" later in this class's description. You use the chosen options to temporarily modify spells you cast. To use an option, you must spend the number of Sorcery Points that it costs. You can use only one Metamagic option on a spell when you cast it unless otherwise noted in one of those options. Whenever you gain a Sorcerer level, you can replace one of your Metamagic options with one you don't know. You gain two more options at Sorcerer level 10 and two more at Sorcerer level 17."}, {"name": "Metamagic Options", "level": 2, "text": "The following options are available to your Metamagic feature. The options are presented in alphabetical order."}, {"name": "Sorcerer Subclass", "level": 3, "text": "You gain a Sorcerer subclass of your choice. A subclass is a specialization that grants you features at certain Sorcerer levels. For the rest of your career, you gain each of your subclass's features that are of your Sorcerer level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Sorcerer levels 8, 12, and 16."}, {"name": "Sorcerous Restoration", "level": 5, "text": "When you finish a Short Rest, you can regain expended Sorcery Points, but no more than a number equal to half your Sorcerer level (round down). Once you use this feature, you can't do so again until you finish a Long Rest."}, {"name": "Subclass Feature", "level": 6, "text": "You gain a feature from your Sorcerer subclass."}, {"name": "Sorcery Incarnate", "level": 7, "text": "If you have no uses of Innate Sorcery left, you can use it if you spend 2 Sorcery Points when you take the Bonus Action to activate it. In addition, while your Innate Sorcery feature is active, you can use up to two of your Metamagic options on each spell you cast."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Metamagic", "level": 10, "text": "Because your magic flows from within you, you can alter your spells to suit your needs; you gain two Metamagic options of your choice from the \"Metamagic Options\" section later in this class's description. You can use only one Metamagic option on a spell when you cast it, unless otherwise noted in one of those options. Whenever you gain a Sorcerer level, you can replace one of your Metamagic options with one you don't know."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 14, "text": "You gain a feature from your Sorcerer subclass."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Metamagic", "level": 17, "text": "Because your magic flows from within you, you can alter your spells to suit your needs; you gain two Metamagic options of your choice from the \"Metamagic Options\" section later in this class's description. You can use only one Metamagic option on a spell when you cast it, unless otherwise noted in one of those options. Whenever you gain a Sorcerer level, you can replace one of your Metamagic options with one you don't know."}, {"name": "Subclass Feature", "level": 18, "text": "You gain a feature from your Sorcerer subclass."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Dimensional Travel is recommended."}, {"name": "Arcane Apotheosis", "level": 20, "text": "While your Innate Sorcery feature is active, you can use one Metamagic option on each of your turns without spending Sorcery Points on it."}]}, {"id": "warlock", "name": "Warlock", "originalName": "Warlock", "source": "PHB 2024", "hitDie": "8", "image": "https://5e.tools/img/classes/XPHB/Warlock.webp", "primaryAbility": ["CHA"], "proficiencies": ["Wis", "Cha"], "tableLabels": ["Invocations", "Cantrips", "Prepared Spells", "Spell Slots", "Slot Level"], "progression": [{"level": 1, "values": ["1", "2", "2", "1", "1"]}, {"level": 2, "values": ["3", "2", "3", "2", "1"]}, {"level": 3, "values": ["3", "2", "4", "2", "2"]}, {"level": 4, "values": ["3", "3", "5", "2", "2"]}, {"level": 5, "values": ["5", "3", "6", "2", "3"]}, {"level": 6, "values": ["5", "3", "7", "2", "3"]}, {"level": 7, "values": ["6", "3", "8", "2", "4"]}, {"level": 8, "values": ["6", "3", "9", "2", "4"]}, {"level": 9, "values": ["7", "3", "10", "2", "5"]}, {"level": 10, "values": ["7", "4", "10", "2", "5"]}, {"level": 11, "values": ["7", "4", "11", "3", "5"]}, {"level": 12, "values": ["8", "4", "11", "3", "5"]}, {"level": 13, "values": ["8", "4", "12", "3", "5"]}, {"level": 14, "values": ["8", "4", "12", "3", "5"]}, {"level": 15, "values": ["9", "4", "13", "3", "5"]}, {"level": 16, "values": ["9", "4", "13", "3", "5"]}, {"level": 17, "values": ["9", "4", "14", "4", "5"]}, {"level": 18, "values": ["10", "4", "14", "4", "5"]}, {"level": 19, "values": ["10", "4", "15", "4", "5"]}, {"level": 20, "values": ["10", "4", "15", "4", "5"]}], "subclasses": [{"name": "Archfey Patron", "shortName": "Archfey", "source": "PHB 2024", "desc": ""}, {"name": "Celestial Patron", "shortName": "Celestial", "source": "PHB 2024", "desc": ""}, {"name": "Fiend Patron", "shortName": "Fiend", "source": "PHB 2024", "desc": ""}, {"name": "Great Old One Patron", "shortName": "Great Old One", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Eldritch Invocation Options", "level": 1, "text": "Eldritch Invocation options appear in alphabetical order."}, {"name": "Eldritch Invocations", "level": 1, "text": "You have unearthed Eldritch Invocations, pieces of forbidden knowledge that imbue you with an abiding magical ability or other lessons. You gain one invocation of your choice, such as Pact of the Tome. Invocations are described in the \"Eldritch Invocation Options\" section later in this class's description. Prerequisites. If an invocation has a prerequisite, you must meet it to learn that invocation. For example, if an invocation requires you to be a level 5+ Warlock, you can select the invocation once you reach Warlock level 5. Replacing and Gaining Invocations. Whenever you gain a Warlock level, you can replace one of your invocations with another one for which you qualify. You can't replace an invocation if it's a prerequisite for another invocation that you have. When you gain certain Warlock levels, you gain more invocations of your choice, as shown in the Invocations column of the Warlock Features table. You can't pick the same invocation more than once unless its description says otherwise."}, {"name": "Pact Magic", "level": 1, "text": "Through occult ceremony, you have formed a pact with a mysterious entity to gain magical powers. The entity is a voice in the shadows—its identity unclear—but its boon to you is concrete: the ability to cast spells. See chapter 7|XPHB|7 for the rules on spellcasting. The information below details how you use those rules with Warlock spells, which appear in the Warlock spell list later in the class's description. Cantrips. You know two Warlock cantrips of your choice. Eldritch Blast and Prestidigitation are recommended. Whenever you gain a Warlock level, you can replace one of your cantrips from this feature with another Warlock cantrip of your choice. When you reach Warlock levels 4 and 10, you learn another Warlock cantrip of your choice, as shown in the Cantrips column of the Warlock Features table. Spell Slots. The Warlock Features table shows how many spell slots you have to cast your Warlock spells of levels 1–5. The table also shows the level of those slots, all of which are the same level. You regain all expended Pact Magic spell slots when you finish a Short Rest or Long Rest. For example, when you're a level 5 Warlock, you have two level 3 spell slots. To cast the level 1 spell Witch Bolt, you must spend one of those slots, and you cast it as a level 3 spell. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To start, choose two level 1 Warlock spells. Charm Person and Hex are recommended. The number of spells on your list increases as you gain Warlock levels, as shown in the Prepared Spells column of the Warlock Features table. Whenever that number increases, choose additional Warlock spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level no higher than what's shown in the table's Slot Level column for your level. When you reach level 6, for example, you learn a new Warlock spell, which can be of levels 1–3. If another Warlock feature gives you spells that you always have prepared, those spells don't count against the number of spells you can prepare with this feature, but those spells otherwise count as Warlock spells for you. Changing Your Prepared Spells. Whenever you gain a Warlock level, you can replace one spell on your list with another Warlock spell of an eligible level. Spellcasting Ability. Charisma is the spellcasting ability for your Warlock spells. Spellcasting Focus. You can use an Arcane Focus as a Spellcasting Focus for your Warlock spells."}, {"name": "Magical Cunning", "level": 2, "text": "You can perform an esoteric rite for 1 minute. At the end of it, you regain expended Pact Magic spell slots but no more than a number equal to half your maximum (round up). Once you use this feature, you can't do so again until you finish a Long Rest."}, {"name": "Warlock Subclass", "level": 3, "text": "You gain a Warlock subclass of your choice. A subclass is a specialization that grants you features at certain Warlock levels. For the rest of your career, you gain each of your subclass's features that are of your Warlock level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Warlock levels 8, 12, and 16."}, {"name": "Subclass Feature", "level": 6, "text": "You gain a feature from your Warlock subclass."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Contact Patron", "level": 9, "text": "In the past, you usually contacted your patron through intermediaries. Now you can communicate directly; you always have the Contact Other Plane spell prepared. With this feature, you can cast the spell without expending a spell slot to contact your patron, and you automatically succeed on the spell's saving throw. Once you cast the spell with this feature, you can't do so in this way again until you finish a Long Rest."}, {"name": "Subclass Feature", "level": 10, "text": "You gain a feature from your Warlock subclass."}, {"name": "Mystic Arcanum", "level": 11, "text": "Your patron grants you a magical secret called an arcanum. Choose one level 6 Warlock spell as this arcanum. You can cast your arcanum spell once without expending a spell slot, and you must finish a Long Rest before you can cast it in this way again. As shown in the Warlock Features table, you gain another Warlock spell of your choice that can be cast in this way when you reach Warlock levels 13 (level 7 spell), 15 (level 8 spell), and 17 (level 9 spell). You regain all uses of your Mystic Arcanum when you finish a Long Rest. Whenever you gain a Warlock level, you can replace one of your arcanum spells with another Warlock spell of the same level."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Mystic Arcanum", "level": 13, "text": "You gain a level 7 Warlock Spell of your choice."}, {"name": "Subclass Feature", "level": 14, "text": "You gain a feature from your Warlock subclass."}, {"name": "Mystic Arcanum", "level": 15, "text": "You gain a level 8 Warlock Spell of your choice."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Mystic Arcanum", "level": 17, "text": "You gain a level 9 Warlock Spell of your choice."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Fate is recommended."}, {"name": "Eldritch Master", "level": 20, "text": "When you use your Magical Cunning feature, you regain all your expended Pact Magic spell slots."}]}, {"id": "wizard", "name": "Mago", "originalName": "Wizard", "source": "PHB 2024", "hitDie": "6", "image": "https://5e.tools/img/classes/XPHB/Wizard.webp", "primaryAbility": ["INT"], "proficiencies": ["Int", "Wis"], "tableLabels": ["Cantrips", "Prepared Spells", "1", "2", "3", "4", "5", "6", "7", "8", "9"], "progression": [{"level": 1, "values": ["3", "4"]}, {"level": 2, "values": ["3", "5"]}, {"level": 3, "values": ["3", "6"]}, {"level": 4, "values": ["4", "7"]}, {"level": 5, "values": ["4", "9"]}, {"level": 6, "values": ["4", "10"]}, {"level": 7, "values": ["4", "11"]}, {"level": 8, "values": ["4", "12"]}, {"level": 9, "values": ["4", "14"]}, {"level": 10, "values": ["5", "15"]}, {"level": 11, "values": ["5", "16"]}, {"level": 12, "values": ["5", "16"]}, {"level": 13, "values": ["5", "17"]}, {"level": 14, "values": ["5", "18"]}, {"level": 15, "values": ["5", "19"]}, {"level": 16, "values": ["5", "21"]}, {"level": 17, "values": ["5", "22"]}, {"level": 18, "values": ["5", "23"]}, {"level": 19, "values": ["5", "24"]}, {"level": 20, "values": ["5", "25"]}], "subclasses": [{"name": "Abjurer", "shortName": "Abjurer", "source": "PHB 2024", "desc": ""}, {"name": "Diviner", "shortName": "Diviner", "source": "PHB 2024", "desc": ""}, {"name": "Evoker", "shortName": "Evoker", "source": "PHB 2024", "desc": ""}, {"name": "Illusionist", "shortName": "Illusionist", "source": "PHB 2024", "desc": ""}], "features": [{"name": "Arcane Recovery", "level": 1, "text": "You can regain some of your magical energy by studying your spellbook. When you finish a Short Rest, you can choose expended spell slots to recover. The spell slots can have a combined level equal to no more than half your Wizard level (round up), and none of the slots can be level 6 or higher. For example, if you're a level 4 Wizard, you can recover up to two levels' worth of spell slots, regaining either one level 2 spell slot or two level 1 spell slots. Once you use this feature, you can't do so again until you finish a Long Rest."}, {"name": "Ritual Adept", "level": 1, "text": "You can cast any spell as a Ritual if that spell has the Ritual tag and the spell is in your spellbook. You needn't have the spell prepared, but you must read from the book to cast a spell in this way."}, {"name": "Spellcasting", "level": 1, "text": "As a student of arcane magic, you have learned to cast spells. See chapter 7|XPHB|7 for the rules on spellcasting. The information below details how you use those rules with Wizard spells, which appear in the Wizard spell list later in the class's description. Cantrips. You know three Wizard cantrips of your choice. Light, Mage Hand, and Ray of Frost are recommended. Whenever you finish a Long Rest, you can replace one of your cantrips from this feature with another Wizard cantrip of your choice. When you reach Wizard levels 4 and 10, you learn another Wizard cantrip of your choice, as shown in the Cantrips column of the Wizard Features table. Spellbook. Your wizardly apprenticeship culminated in the creation of a unique book: your spellbook. It is a Tiny object that weighs 3 pounds, contains 100 pages, and can be read only by you or someone casting Identify. You determine the book's appearance and materials, such as a gilt-edged tome or a collection of vellum bound with twine. The book contains the level 1+ spells you know. It starts with six level 1 Wizard spells of your choice. Detect Magic, Feather Fall, Mage Armor, Magic Missile, Sleep, and Thunderwave are recommended. Whenever you gain a Wizard level after 1, add two Wizard spells of your choice to your spellbook. Each of these spells must be of a level for which you have spell slots, as shown in the Wizard Features table. The spells are the culmination of arcane research you do regularly. Spell Slots. The Wizard Features table shows how many spell slots you have to cast your level 1+ spells. You regain all expended slots when you finish a Long Rest. Prepared Spells of Level 1+. You prepare the list of level 1+ spells that are available for you to cast with this feature. To do so, choose four spells from your spellbook. The chosen spells must be of a level for which you have spell slots. The number of spells on your list increases as you gain Wizard levels, as shown in the Prepared Spells column of the Wizard Features table. Whenever that number increases, choose additional Wizard spells until the number of spells on your list matches the number in the table. The chosen spells must be of a level for which you have spell slots. For example, if you're a level 3 Wizard, your list of prepared spells can include six spells of levels 1 and 2 in any combination, chosen from your spellbook. If another Wizard feature gives you spells that you always have prepared, those spells don't count against the number of spells you can prepare with this feature, but those spells otherwise count as Wizard spells for you. Changing Your Prepared Spells. Whenever you finish a Long Rest, you can change your list of prepared spells, replacing any of the spells there with spells from your spellbook. Spellcasting Ability. Intelligence is your spellcasting ability for your Wizard spells. Spellcasting Focus. You can use an Arcane Focus or your spellbook as a Spellcasting Focus for your Wizard spells. Expanding and Replacing a Spellbook. The spells you add to your spellbook as you gain levels reflect your ongoing magical research, but you might find other spells during your adventures that you can add to the book. You could discover a Wizard spell on a Spell Scroll, for example, and then copy it into your spellbook. Copying a Spell into the Book. When you find a level 1+ Wizard spell, you can copy it into your spellbook if it's of a level you can prepare and if you have time to copy it. For each level of the spell, the transcription takes 2 hours and costs 50 GP. Afterward you can prepare the spell like the other spells in your spellbook. Copying the Book. You can copy a spell from your spellbook into another book. This is like copying a new spell into your spellbook but faster, since you already know how to cast the spell. You need spend only 1 hour and 10 GP for each level of the copied spell. If you lose your spellbook, you can use the same procedure to transcribe the Wizard spells that you have prepared into a new spellbook. Filling out the remainder of the new book requires you to find new spells to do so. For this reason, many wizards keep a backup spellbook."}, {"name": "Scholar", "level": 2, "text": "While studying magic, you also specialized in another field of study. Choose one of the following skills in which you have proficiency: Arcana, History, Investigation, Medicine, Nature, or Religion. You have Expertise in the chosen skill."}, {"name": "Wizard Subclass", "level": 3, "text": "You gain a Wizard subclass of your choice. A subclass is a specialization that grants you features at certain Wizard levels. For the rest of your career, you gain each of your subclass's features that are of your Wizard level or lower."}, {"name": "Ability Score Improvement", "level": 4, "text": "You gain the Ability Score Improvement feat or another {@5etools feat|feats.html of your choice for which you qualify. You gain this feature again at Wizard levels 8, 12, and 16."}, {"name": "Memorize Spell", "level": 5, "text": "Whenever you finish a Short Rest, you can study your spellbook and replace one of the level 1+ Wizard spells you have prepared for your Spellcasting feature with another level 1+ spell from the book."}, {"name": "Subclass Feature", "level": 6, "text": "You gain a feature from your Wizard Subclass."}, {"name": "Ability Score Improvement", "level": 8, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 10, "text": "You gain a feature from your Wizard Subclass."}, {"name": "Ability Score Improvement", "level": 12, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Subclass Feature", "level": 14, "text": "You gain a feature from your Wizard Subclass."}, {"name": "Ability Score Improvement", "level": 16, "text": "You gain the Ability Score Improvement Feat or another {@5etools feat|feats.html of your choice for which you qualify."}, {"name": "Spell Mastery", "level": 18, "text": "You have achieved such mastery over certain spells that you can cast them at will. Choose a level 1 and a level 2 spell in your spellbook that have a casting time of an action. You always have those spells prepared, and you can cast them at their lowest level without expending a spell slot. To cast either spell at a higher level, you must expend a spell slot. Whenever you finish a Long Rest, you can study your spellbook and replace one of those spells with an eligible spell of the same level from the book."}, {"name": "Epic Boon", "level": 19, "text": "You gain an Epic Boon feat or another {@5etools feat|feats.html of your choice for which you qualify. Boon of Spell Recall is recommended."}, {"name": "Signature Spells", "level": 20, "text": "Choose two level 3 spells in your spellbook as your signature spells. You always have these spells prepared, and you can cast each of them once at level 3 without expending a spell slot. When you do so, you can't cast them in this way again until you finish a Short Rest or Long Rest. To cast either spell at a higher level, you must expend a spell slot."}]}];
